  // Hills with light
  brush.fill("#a8d8ff", 0.8); // Lighter hills
  brush.fill("#d8eaff", 0.6); // Misty blue hills

  // Horizon
  brush.fill("#d8eaff", 0.6); // Lighter blue
  brush.fill("#f0f0f0", 0.8); // Grayish blue

  // Trees and foliage
  brush.fill("#228b22", 0.8); // Green
  brush.fill("#4682b4", 0.5); // Dark green
  brush.fill("#a0d0e5", 0.7); // Lime green

  // Rocks and small details
  brush.fill("#8b4513", 0.6); // Brownish red
  brush.fill("#8b4513", 0.4); // Darker red
  brush.fill("#5f9ea0", 0.7); // Dark green

  // Grass
  brush.fill("#91a38d", 0.8); // Medium green
  brush.fill("#98fb96", 0.6); // Light green

  // Optional: small details
